\begin{proposition}[The conormal filtration and its exact section criterion]\label{cdp:st:A.1.1}
\StatementRecord{cdp:st:A.1.1}{proved}{}{the hypotheses, notation and definitions stated here; the explicit constructions and calculations in the proof}
\label{wbII:prop:criterion}\label{wbII:prop:filtration}\label{wbII:lem:conormal}\label{wbII:lem:conormal-injective}\label{wbII:prop:missing-global-section-criterion}\label{wbII:prop:missing-cotangent-filtration}
The conormal map $d:N^*\to V$, defined by $[F]\mapsto dF|_S$ for a local defining equation $F$, is injective. With $K=\ker(V\to Q)$, there are canonical exact sequences
\begin{align}
0&\longrightarrow N^*\xrightarrow{d}K\longrightarrow T\longrightarrow0,
\label{cdp:A:filtration1}\\
0&\longrightarrow K\longrightarrow V\longrightarrow Q\longrightarrow0.
\label{cdp:A:filtration2}
\end{align}
Let $\partial_A:H^0(S,Q\otimes A)\to H^1(S,K\otimes A)$ and $\delta_A:H^0(S,T\otimes A)\to H^1(S,N^*\otimes A)$ be their connecting maps. Then
\[
 H^0(S,V\otimes A)=0
 \quad\Longleftrightarrow\quad
 H^0(S,K\otimes A)=0\ \hbox{and}\ \partial_A\hbox{ is injective}.
\tag{A.1}\label{cdp:eq:A.1}
\]
Under the explicit hypotheses $H^0(S,N^*\otimes A)=0$ and $H^0(S,Q\otimes A)=0$, $H^0(S,V\otimes A)$ is canonically $\ker\delta_A$.
\end{proposition}

\begin{proposition}[Unitary-flat differentials on every compact reduced complex surface]\label{cdp:st:A.4.7}
\StatementRecord{cdp:st:A.4.7}{proved}{}{the hypotheses, notation and definitions stated here; the explicit constructions and calculations in the proof}

Let $S$ be a compact reduced complex surface, let $\mathbb A$ be a rank-one unitary complex local system on its underlying topological space, and let $A=\mathbb A\otimes_{\C}\OO_S$ be its associated holomorphic line bundle. There is a canonical complex-linear injection
\[
 H^0(S,\widetilde\Omega_S^1\otimes A)
       \longrightarrow H^1(S,\mathbb A).
 \tag{A.20}\label{cdp:eq:A.20}
\]
The construction uses continuous local primitives that are holomorphic on the normalization; it does not assert that those primitives are holomorphic on a non-seminormal surface.
\end{proposition}

\begin{proposition}[CDP20 Proposition 7.3 with a complete replacement proof]\label{cdp:st:A.4.9}
\StatementRecord{cdp:st:A.4.9}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:st:D.1.9}; \cref{cdp:st:C.3.1}; \cref{cdp:st:A.4.8}; \cite[\S1 and the central-extension diagram in the proof of Lemma~1.1]{SS2002}; \cite[\S2.1.1 and Theorem~2.2]{Albanese2020}; \cite[\S2.1.2 and Proposition~2.3]{Albanese2020}; \cref{cdp:st:D.1.8}; \cref{cdp:st:A.4.7}; \cref{cdp:st:A.4.2}; \cref{cdp:eq:A.24}}

Let $Y$ be a connected smooth compact complex threefold with $H^1(Y,\Z)=H^2(Y,\Z)=0$, algebraic dimension one and holomorphic algebraic reduction $g:Y\to C$. There is a dense open subset of $\Pic(Y)$, whose complement is a proper complex analytic subset, such that
\[
 H^0\bigl((Y_c)_{\rm red},
       \widetilde\Omega^1_{(Y_c)_{\rm red}}\otimes L|_{(Y_c)_{\rm red}}\bigr)=0
 \tag{A.23}\label{cdp:eq:A.23}
\]
for every singular reduced fibre support and every $L$ in that subset. In fact the transgression twists $L_r$ of \ref{cdp:st:D.1.9} satisfy \eqref{cdp:eq:A.23} on every reduced fibre support, including smooth and reducible supports, for every real irrational $r$.
\end{proposition}

\begin{theorem}[The Euler sign for every degeneration and its equality criterion]
\label{cdp:st:C.2.G.1}
\StatementRecord{cdp:st:C.2.G.1}{proved}{}{\ExternalPaperRef{}{3.6}{II}; \ExternalPaperRef{}{5.14}{II};
\ExternalPaperRef{}{6.2}{II}; \ExternalPaperRef{}{6.3}{II};
\ref{cdp:st:C.2.MH.1}; \ref{cdp:st:C.2.MH.2};
\ExternalPaperRef{}{8.26}{II}; \ExternalPaperRef{}{8.32}{II};
\ExternalPaperRef{}{8.36}{II}; \ExternalPaperRef{}{8.37}{II};
\ref{cdp:st:C.2.INT.1}; \ref{cdp:st:C.2.INT.2};
\ref{cdp:st:C.2.INT.3}; \ref{cdp:st:C2a};
\cite[Proposition~2.1 and Theorem~2.2, pp.~842--843]{Peters2021}}

Let $Y$ be a connected smooth compact complex threefold with
$b_1(Y)=b_2(Y)=0$, and let $f:Y\to B$ be a proper surjective
holomorphic map with connected fibres to a smooth compact curve.
Assume that the smooth general fibre is a complex two-torus.
The full fibres may have arbitrary positive component multiplicities
and their reduced supports may have arbitrary singularities. Then
\[
 B\simeq\PP^1,\qquad
 c_3(Y)=e(Y)\in\{0,2\},\qquad b_3(Y)=2-c_3(Y).
 \tag{C.G.1}\label{cdp:eq:C.G.1}
\]
Every reduced fibre support has nonnegative Euler number.
An irreducible singular support with rational normalization
resolution has Euler number two; every other irreducible support
has Euler number zero.

The equality $c_3(Y)=0$ holds exactly when every support has one
of the following descriptions. A smooth irreducible support has
a finite unramified torus cover. A singular irreducible support
has smooth minimal elliptic ruled or smooth minimal Hopf
normalization. A reducible support has normalization a disjoint
union of smooth minimal Hopf or non-K\"ahler elliptic surfaces;
its reduced conductor image and inverse image are disjoint
unions of smooth elliptic curves, and the conductor branch maps
are finite unramified covers. Each description concerns the
normalization and resolution maps of the actual fibre. In
particular the full-fibre and conductor multiplicities are
retained.
\end{theorem}

\begin{proposition}[Proved exclusion of Enoki components]\label{cdp:st:C.2.INT.2}
\StatementRecord{cdp:st:C.2.INT.2}{proved}{}{the hypotheses, notation and definitions stated here; \ExternalPaperRef{proposition~}{4.3}{II}; \cref{cdp:st:C.2.INT.1}; \ExternalPaperRef{proposition~}{6.3}{II}; \cite[Lemma~2.22 and the following paragraph]{Dloussky2006}; \ExternalPaperRef{proposition~}{5.19}{II}; \cref{cdp:eq:C.INT.5}; \cref{cdp:eq:C.INT.7}; \cref{cdp:eq:C.INT.6}}


Let $f:Y\to B$ be a proper connected-fibre map from a
smooth compact complex threefold with $H^2(Y,\Q)=0$
and general fibre a complex two-torus. No component
of a reducible fibre has normalization resolution
with Enoki minimal model.
\end{proposition}

\begin{proposition}[Every torus-degeneration fibre has even Euler number]\label{cdp:st:C.2.UN.1}
\StatementRecord{cdp:st:C.2.UN.1}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:eq:C.UN.3}; \cref{cdp:eq:C.UN.4}}

Let $f:Y\to B$ be a proper holomorphic map from a smooth complex
threefold to a smooth complex curve, with connected fibres and smooth
general fibre a complex two-torus. For every $b\in B$,
\[
                    e((Y_b)_{\rm red})\in2\Z.       \tag{C.UN.1}\label{cdp:eq:C.UN.1}
\]
This assertion allows arbitrary multiplicities and singularities and
imposes no K\"ahler or Betti-number hypothesis on $Y$.
\end{proposition}

\begin{proposition}[Proved exclusion of primary Kodaira general fibres]\label{cdp:st:C.3.10}
\StatementRecord{cdp:st:C.3.10}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:st:C.3.9}; \cite[pp.~373--374]{Borcea1984}; \cref{cdp:st:D.1.12}; \cref{cdp:st:D.1.9}; \cref{cdp:st:D.1.7}; \cite[\S1]{SS2002}; \cite[Remark~1]{Borcea1984}; \cref{cdp:eq:C.PK.4}; \cite[\S3]{Borcea1984}; \cref{cdp:st:D.2.3}; \cite[Theorem~2.18 and \S\S2.19--2.21]{Steenbrink1976}; \cref{cdp:eq:C.PK.5}; \cref{cdp:eq:C.PK.1}; \cref{cdp:eq:C.PK.2}; \cref{cdp:eq:C.PK.7}}


A compact complex threefold with $b_1(Y)=b_2(Y)=0$ and
$a(Y)=1$ cannot have a holomorphic algebraic reduction
$f:Y\to\PP^1$ whose general fibre is a primary Kodaira
surface. Together with \ref{cdp:st:C.3.9} this excludes both Kodaira
types using only rational Betti-number vanishing.
\end{proposition}

\begin{proposition}[Proved actual occurrence of both Hopf types]\label{cdp:st:C.3.6}
\StatementRecord{cdp:st:C.3.6}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:eq:C.H.1}}


There are compact complex threefolds with $b_1=b_2=0$ and $a=1$
whose holomorphic algebraic reduction is a smooth bundle over
$\PP^1$ with primary Hopf fibre. There are also such threefolds
with secondary Hopf fibre. In these examples every fibre has Euler
number zero and $c_3=0$.
\end{proposition}

\begin{proposition}[Proved exclusion of bielliptic fibres]\label{cdp:st:C.3.7}
\StatementRecord{cdp:st:C.3.7}{proved}{}{the hypotheses, notation and definitions stated here; \cite[Proposition~2, pp.~605--608]{Kawai1969}; \cite[Theorem~1.1]{Peters1990}}


A compact complex threefold $Y$ with $b_1(Y)=b_2(Y)=0$ has no
proper connected-fibre holomorphic map to a compact curve whose
general fibre is bielliptic.
\end{proposition}

\begin{proposition}[Proved exclusion of elliptic Hopf general fibres]\label{cdp:st:C.3.8}
\StatementRecord{cdp:st:C.3.8}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:st:C.3.1}; \cite[Proposition~3.1 and its proof]{SS2002}}


The very general Hopf fibre of the algebraic reduction in \ref{cdp:st:C.3.1}
has algebraic dimension zero. In particular neither primary nor
secondary Hopf surfaces of algebraic dimension one can be its
general fibre. This exclusion uses no restriction-surjectivity
assertion from CDP98 or CDP20.
\end{proposition}

\begin{proposition}[Proved exclusion of secondary Kodaira general fibres]\label{cdp:st:C.3.9}
\StatementRecord{cdp:st:C.3.9}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:st:D.1.9}; \CompendiumRef{II}{cdp:st:E4}; \cref{cdp:st:D.1.7}; \cref{cdp:eq:C.SK.1}; \cite[Theorem~4 and Remark~1]{Borcea1984}; \cite[\S1, pp.~2--3]{SS2002}; \cref{cdp:eq:C.SK.2}; \cref{cdp:eq:C.SK.3}; \cref{cdp:eq:C.SK.4}; \cref{cdp:eq:C.SK.5}}


A compact complex threefold with $b_1(Y)=b_2(Y)=0$ and
$a(Y)=1$ cannot have a holomorphic algebraic reduction
$f:Y\to\PP^1$ whose general fibre is a secondary Kodaira
surface. Rational Betti-number vanishing suffices; no integral
torsion-freeness of the fibre is assumed.
\end{proposition}

\begin{proposition}[Integral twists and the normalization-map exception]\label{cdp:st:C5b}
\StatementRecord{cdp:st:C5b}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:eq:C.8}; \cref{cdp:st:C5a}; \cref{cdp:eq:C.9}}

For $n\in\Z$ define
\[
 r_1(n)\equiv n\pmod3,\quad 0\le r_1(n)<3,
 \qquad r_2(n)\equiv3n\pmod4,\quad0\le r_2(n)<4,
\]
\begin{gather*}
 d(n)=\frac{n-4r_1(n)-3r_2(n)}{12},\qquad
 \epsilon_n=\begin{cases}0&3\mid n,\\1&3\nmid n.\end{cases}
\\
 u(n)=\max\{d(n)+1,0\},\qquad
 v(n)=\max\{-d(n)-1,0\}.
\end{gather*}
The coarse direct images of $T_X\otimes M_n$ are
\begin{align*}
 f_*(T_X\otimes M_n)&=\OO(d(n))\oplus\OO(d(n-1)),\\
 R^1f_*(T_X\otimes M_n)&=\OO(d(n))\oplus\OO(d(n-1))\oplus\OO(d(n+2)),\\
 R^2f_*(T_X\otimes M_n)&=\OO(d(n+6))\oplus\C_{p_1}^{\epsilon_n}.\tag{C.5}\label{cdp:eq:C.5}
\end{align*}
Their global cohomology dimensions are
\begin{align*}
 h^0&=u(n)+u(n-1),\\
 h^1&=v(n)+v(n-1)+u(n)+u(n-1)+u(n+2),\\
 h^2&=v(n)+v(n-1)+v(n+2)+u(n+6)+\epsilon_n,\\
 h^3&=v(n+6).                                             \tag{C.6}\label{cdp:eq:C.6}
\end{align*}
The natural map $H^2(X,T_X\otimes M_n)\to H^2(\mathrm dP_6,K_{\mathrm dP_6})=\C$ has rank one exactly for
\[
 n\in\{-6,-3,-2\}\cup\Z_{\ge0};                         \tag{C.7}\label{cdp:eq:C.7}
\]
it is zero for all other integers. In particular $M_{-1}$ has tangent cohomology $(0,0,1,0)$ and a zero map to the normalization target.
\end{proposition}

\begin{proposition}[Every nonintegral twist and its resonance lengths]\label{cdp:st:C5c}
\StatementRecord{cdp:st:C5c}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:eq:C.13}}

Retain the fixed marked functions $\tau,\mu,\beta_c$ and put $\rho=\tau(z_1)$. For $z\notin\Z$, let $\mathcal R_z$ be the set of regular base points at which integers $(n,p,q,r)$ satisfy
\[
 q\tau+r\mu=p,\qquad z=n-6q\mu-r\beta_c.               \tag{C.10}\label{cdp:eq:C.10}
\]
Let
\[
 \Lambda_1=\Z+(3\beta_c(z_1)+4-2\rho)\Z,\quad
 \Lambda_2=\Z+(2\beta_c(z_2)+3-3i)\Z.
\]
Set $\ell_1(z)=1+\epsilon_n$ for $z=n+k(3\beta_c(z_1)+4-2\rho)$ with $k\ne0$, and zero off $\Lambda_1$. Set $\ell_2(z)=1$ for $z=n+k(2\beta_c(z_2)+3-3i)$ with $k\ne0$ and $n\equiv1,2\pmod4$, and zero otherwise. Then $\mathcal R_z$ is finite. With $N_z=|\mathcal R_z|$ and $J_z=2N_z+\ell_1(z)+\ell_2(z)$, we have
\[
 (h^0,h^1,h^2,h^3)(X,T_X\otimes M_z)=(0,J_z,1+J_z,0),  \tag{C.11}\label{cdp:eq:C.11}
\]
and, writing $\mathfrak m_t$ for the maximal ideal of $\OO_{B,t}$,
\begin{align*}
R^1f_*(T_X\otimes M_z)&=
 \bigoplus_{t\in\mathcal R_z}\C_t^2
 \oplus\C_{p_1}^{\ell_1(z)}\oplus\C_{p_2}^{\ell_2(z)},\\
R^2f_*(T_X\otimes M_z)&=
 \C_{p_0}\oplus\bigoplus_{t\in\mathcal R_z}\OO_{B,t}/\mathfrak m_t^2
 \oplus\C_{p_1}^{\ell_1(z)}\oplus\C_{p_2}^{\ell_2(z)}.\tag{C.12}\label{cdp:eq:C.12}
\end{align*}
The natural map to $H^2(\mathrm dP_6,K_{\mathrm dP_6})$ is surjective for all these nonintegral twists.
\end{proposition}

\begin{proposition}[Counterexample: The square theta formula for arbitrary sections]\label{cdp:st:E18}
\StatementRecord{cdp:st:E18}{proved}{}{the hypotheses, notation and definitions stated here; \cref{cdp:eq:E-theta-general}; \cref{cdp:st:E5}}

The square-only formula in Lead~9 is false as a local period
identity for arbitrary elliptic sections and linearizations.
The exact formula for the theta expression specified there is
\eqref{cdp:eq:E-theta-general}. The assertion for the actual original
period family remains true, by its equation $\wp(\mu)=0$.
\end{proposition}

\begin{proposition}[The theta determinant and its exact rank locus for $X_c$]\label{cdp:st:E8}
\StatementRecord{cdp:st:E8}{proved}{}{the hypotheses, notation and definitions stated here; the explicit constructions and calculations in the proof}

Use the period convention
$\Omega=\left(\begin{smallmatrix}\tau&\mu\\\mu&\beta/6\end{smallmatrix}\right)$,
Jacobi's odd theta function with periods $1,\tau$, and
$\beta/6=(i/\pi)\log(\vartheta_1(\mu,\tau)/\eta(\tau))+\text{constant}$.
Writing $h=\partial_\mu\log\vartheta_1$, one has the identity
\begin{equation}\label{cdp:eq:E-theta-general}
 \det\frac{d\Omega}{d\tau}
 =-\left(\mu'-\frac{i}{2\pi}h\right)^2
       -\frac{\wp(\mu,\tau)}{4\pi^2}.
\end{equation}
For the actual AC period branch $\wp(\mu,\tau)=0$, this becomes
\[
 \det\frac{d\Omega}{d\tau}
       =-\frac{g_2(\tau)^2}{36\pi^2g_3(\tau)}.
\]
On the smooth root-family base, the Kodaira--Spencer tensor has rank
one at the order-three point and rank two at every other finite
point, including the order-four point. Its determinant has order
two at the order-three point. The logarithmic tensor at the cusp
has rank two.
\end{proposition}

\begin{proposition}[Counterexample: The universal two-vector-field bound]\label{inv:E2.4}
\StatementRecord{inv:E2.4}{proved}{}{the hypotheses, notation and definitions stated here; \citet[Corollary 1.3; verified preprint p.~2]{HKP2000}; \citet[Remarks 1.2 and 9.26]{AC2026}; \cref{inv:E2.2}}

The assertion that every complex structure on $S^6$ has
$h^0(T)\le2$, printed in
\citet[Corollary 1.3; verified preprint p.~2]{HKP2000}
and repeated in \citet[Remarks 1.2 and 9.26]{AC2026}, is false
for the comb members.
\end{proposition}
